    };

    const save_edit = async () => {
        editModal.hide();
        if (loading_spinner.value) return;
        try {
            
            loading_spinner.value = true;
            const response = await axiosInstance.put(`/work_orders/${editingRow.value.id}`, {
                name: editingRow.value.name,
                short_name: editingRow.value.short_name,
                status: editingRow.value.status
            });
            
            if (response.status === 200) {
                const index = work_orders.value.findIndex(item => item.id === editingRow.value.id);
                if (index !== -1) {
                    work_orders.value[index].name = editingRow.value.name;
                    work_orders.value[index].short_name = editingRow.value.short_name;
                    work_orders.value[index].status = editingRow.value.status;
